import https from 'node:https';
import { config } from '../config/index.js';

const STRIPE_API = 'https://api.stripe.com';

/** Flattens { a: 1, metadata: { b: 2 } } into Stripe's form encoding (metadata[b]=2). */
function formEncode(params, prefix = '') {
  const parts = [];
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue;
    const name = prefix ? `${prefix}[${key}]` : key;
    if (typeof value === 'object') parts.push(formEncode(value, name));
    else parts.push(`${encodeURIComponent(name)}=${encodeURIComponent(String(value))}`);
  }
  return parts.filter(Boolean).join('&');
}

/** POST a form-encoded request to the Stripe API and resolve with the JSON response. */
export function stripePost(path, params, { apiKey = config.stripeSecretKey } = {}) {
  if (!apiKey) return Promise.reject(new Error('Stripe is not configured: set STRIPE_SECRET_KEY'));
  const body = formEncode(params);
  const url = new URL(path, STRIPE_API);
  return new Promise((resolve, reject) => {
    const req = https.request(url, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${apiKey}`,
        'content-type': 'application/x-www-form-urlencoded',
        'content-length': Buffer.byteLength(body),
        accept: 'application/json',
      },
    }, res => {
      let data = '';
      res.setEncoding('utf8');
      res.on('data', chunk => (data += chunk));
      res.on('end', () => {
        let json;
        try { json = JSON.parse(data); } catch (e) { return reject(e); }
        if (res.statusCode >= 400) {
          return reject(new Error(`stripe ${res.statusCode}: ${json?.error?.message ?? data}`));
        }
        resolve(json);
      });
    });
    req.on('error', reject);
    req.end(body);
  });
}

/** Creates a PaymentIntent. `amount` is in the smallest currency unit (e.g. cents). */
export function createPaymentIntent({ amount, currency, metadata }) {
  return stripePost('/v1/payment_intents', {
    amount,
    currency,
    metadata,
    automatic_payment_methods: { enabled: true },
  });
}

