import express from 'express';
import { requireAuth } from '../auth/middleware.js';
import * as stripe from '../clients/stripe.js';

const MIN_AMOUNT = 50; // Stripe's minimum charge is ~50 cents for most currencies.

function validatePayment(input) {
  const errors = [];
  if (!Number.isInteger(input?.amount) || input.amount < MIN_AMOUNT) {
    errors.push(`amount must be an integer of at least ${MIN_AMOUNT} (smallest currency unit)`);
  }
  if (typeof input?.currency !== 'string' || !/^[a-z]{3}$/i.test(input.currency)) {
    errors.push('currency must be a 3-letter ISO code');
  }
  return errors;
}

export function paymentsRouter(client = stripe) {
  const router = express.Router();

  router.post('/payments/intents', requireAuth, express.json(), async (req, res, next) => {
    const errors = validatePayment(req.body);
    if (errors.length) return res.status(400).json({ errors });
    try {
      const intent = await client.createPaymentIntent({
        amount: req.body.amount,
        currency: req.body.currency.toLowerCase(),
        metadata: { userId: String(req.user.userId) },
      });
      res.status(201).json({ id: intent.id, clientSecret: intent.client_secret, status: intent.status });
    } catch (err) {
      next(err);
    }
  });

  return router;
}

