import assert from 'node:assert/strict';
import { createApp } from '../src/server.js';
import { createStore } from '../src/store.js';
import { createSession } from '../src/auth/middleware.js';
import { formEncode } from '../src/clients/stripe.js';

async function withApp(payments, fn) {
  const server = createApp(createStore(), { payments }).listen(0);
  await new Promise(r => server.once('listening', r));
  try {
    await fn(`http://127.0.0.1:${server.address().port}`);
  } finally {
    server.close();
  }
}

const fakeClient = calls => ({
  async createPaymentIntent(args) {
    calls.push(args);
    return { id: 'pi_123', client_secret: 'pi_123_secret', status: 'requires_payment_method' };
  },
});

test('formEncode flattens nested objects', () => {
  assert.equal(
    formEncode({ amount: 500, metadata: { userId: 'u 1' }, skip: undefined }),
    'amount=500&metadata%5BuserId%5D=u%201',
  );
});

test('requires a session', async () => {
  await withApp(fakeClient([]), async base => {
    const res = await fetch(`${base}/payments/intents`, { method: 'POST' });
    assert.equal(res.status, 401);
  });
});

test('validates amount and currency', async () => {
  const calls = [];
  await withApp(fakeClient(calls), async base => {
    const res = await fetch(`${base}/payments/intents`, {
      method: 'POST',
      headers: { authorization: `Bearer ${createSession('u1')}`, 'content-type': 'application/json' },
      body: JSON.stringify({ amount: 10, currency: 'dollars' }),
    });
    assert.equal(res.status, 400);
    assert.equal((await res.json()).errors.length, 2);
    assert.equal(calls.length, 0);
  });
});

test('creates a payment intent', async () => {
  const calls = [];
  await withApp(fakeClient(calls), async base => {
    const res = await fetch(`${base}/payments/intents`, {
      method: 'POST',
      headers: { authorization: `Bearer ${createSession('u1')}`, 'content-type': 'application/json' },
      body: JSON.stringify({ amount: 1999, currency: 'USD' }),
